-- deploy28i: remove the stray (kses-escaped) inline script text from two Home V2 Elementor HTML widgets (Bestsellers pager, section reveal).
-- The behaviour now ships in onyx-child/assets/js/home-v2.js. Idempotent; backs up the original _elementor_data once to _onyx_elementor_data_bak28i.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_520_ci;
INSERT INTO wp_postmeta (post_id,meta_key,meta_value) SELECT m.post_id,'_onyx_elementor_data_bak28i',m.meta_value FROM wp_postmeta m WHERE m.post_id=(SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) AND m.meta_key='_elementor_data' AND NOT EXISTS (SELECT 1 FROM wp_postmeta b WHERE b.post_id=m.post_id AND b.meta_key='_onyx_elementor_data_bak28i');
UPDATE wp_postmeta SET meta_value=REPLACE(meta_value,'(function(){var s=document.currentScript,sec=s&amp;&amp;s.closest(''.hv2-best2'');if(!sec)return;var ul=sec.querySelector(''.hv2-products ul.products'');if(!ul)return;var nav=sec.querySelector(''.hv2-b2-pager''),c=nav.querySelector(''.hv2-b2-count''),pv=nav.querySelector(''.hv2-b2-prev''),nx=nav.querySelector(''.hv2-b2-next'');\\nfunction step(){var li=ul.querySelector(''li.product'');if(!li)return ul.clientWidth;var g=parseFloat(getComputedStyle(ul).columnGap)||0;var per=Math.max(1,Math.floor((ul.clientWidth+g)\\/(li.offsetWidth+g)));return per*(li.offsetWidth+g);}\\nfunction upd(){var st=step(),max=ul.scrollWidth-ul.clientWidth,n=max&gt;2?Math.ceil(max\\/st)+1:1,p=max&gt;2?Math.min(n,Math.round(ul.scrollLeft\\/st)+1):1;if(ul.scrollLeft&gt;=max-2)p=n;c.textContent=p+''\\/''+n;pv.disabled=ul.scrollLeft=max-2;nav.hidden=n&lt;2;}\\npv.addEventListener(&#039;click&#039;,function(){ul.scrollBy({left:-step(),behavior:&#039;smooth&#039;});});nx.addEventListener(&#039;click&#039;,function(){ul.scrollBy({left:step(),behavior:&#039;smooth&#039;});});\\nul.addEventListener(&#039;scroll&#039;,function(){window.requestAnimationFrame(upd);},{passive:true});window.addEventListener(&#039;resize&#039;,upd);upd();})();','') WHERE post_id=(SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) AND meta_key='_elementor_data' AND LOCATE('(function(){var s=document.currentScript,sec=s&amp;&amp;s.closest(''.hv2-best2'');if(!sec)return;var ul=sec.querySelector(''.hv2-products ul.products'');if(!ul)return;var nav=sec.querySelector(''.hv2-b2-pager''),c=nav.querySelector(''.hv2-b2-count''),pv=nav.querySelector(''.hv2-b2-prev''),nx=nav.querySelector(''.hv2-b2-next'');\\nfunction step(){var li=ul.querySelector(''li.product'');if(!li)return ul.clientWidth;var g=parseFloat(getComputedStyle(ul).columnGap)||0;var per=Math.max(1,Math.floor((ul.clientWidth+g)\\/(li.offsetWidth+g)));return per*(li.offsetWidth+g);}\\nfunction upd(){var st=step(),max=ul.scrollWidth-ul.clientWidth,n=max&gt;2?Math.ceil(max\\/st)+1:1,p=max&gt;2?Math.min(n,Math.round(ul.scrollLeft\\/st)+1):1;if(ul.scrollLeft&gt;=max-2)p=n;c.textContent=p+''\\/''+n;pv.disabled=ul.scrollLeft=max-2;nav.hidden=n&lt;2;}\\npv.addEventListener(&#039;click&#039;,function(){ul.scrollBy({left:-step(),behavior:&#039;smooth&#039;});});nx.addEventListener(&#039;click&#039;,function(){ul.scrollBy({left:step(),behavior:&#039;smooth&#039;});});\\nul.addEventListener(&#039;scroll&#039;,function(){window.requestAnimationFrame(upd);},{passive:true});window.addEventListener(&#039;resize&#039;,upd);upd();})();',meta_value)>0;
UPDATE wp_postmeta SET meta_value=REPLACE(meta_value,'(function(){var d=document.documentElement;if(!(\\"IntersectionObserver\\" in window)||matchMedia(\\"(prefers-reduced-motion: reduce)\\").matches)return;d.classList.add(\\"hv2-anim\\");var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add(\\"hv2-in\\");io.unobserve(e.target);}});},{rootMargin:\\"0px 0px -8% 0px\\"});function go(){document.querySelectorAll(\\".hv2-sec\\").forEach(function(s,i){if(i&gt;0)io.observe(s);else s.classList.add(\\"hv2-in\\");});}document.readyState!==\\"loading\\"?go():document.addEventListener(\\"DOMContentLoaded\\",go);})();','') WHERE post_id=(SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) AND meta_key='_elementor_data' AND LOCATE('(function(){var d=document.documentElement;if(!(\\"IntersectionObserver\\" in window)||matchMedia(\\"(prefers-reduced-motion: reduce)\\").matches)return;d.classList.add(\\"hv2-anim\\");var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add(\\"hv2-in\\");io.unobserve(e.target);}});},{rootMargin:\\"0px 0px -8% 0px\\"});function go(){document.querySelectorAll(\\".hv2-sec\\").forEach(function(s,i){if(i&gt;0)io.observe(s);else s.classList.add(\\"hv2-in\\");});}document.readyState!==\\"loading\\"?go():document.addEventListener(\\"DOMContentLoaded\\",go);})();',meta_value)>0;
DELETE FROM wp_postmeta WHERE post_id=(SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) AND meta_key IN ('_elementor_element_cache','_elementor_css');
